using (StudentEditorForm dlg = new StudentEditorForm(txtStudent.Text))                 {                     if (dlg.ShowDialog(this) != DialogResult.OK) return;                      string used = UserService.AddStudent(dlg.Number, dlg.FullName, dlg.Email, dlg.Password);                     txtStudent.Text = dlg.Number;                     ShowStudentName();                     if (string.IsNullOrEmpty(dlg.Password))                         Ui.Info("The student was added.

Temporary password: " + used +                                 "

Give it to the student. It is not shown again.");                     else                         Ui.Info("The student was added.");                 }

